/**
 * Mobile Digital Garage / Vehicle Passport (spec Phase 5): the customer-facing summary behind a capability link.
 * Everything here is derived from records (ownership, ROs, OEM schedule, recalls); nothing is generated by a model.
 * The chat (garage_chat@1) answers only from passportFacts(), and its answer must pass checkDraft against them.
 */
import { all, get, run, tx } from './db.ts';
import { clock, daysBetween } from './clock.ts';
import { audit } from './audit.ts';
import { vehicleRoadmap, equityPeak, estimateMiles, fmtMiles, SCHEDULE_SOURCE_NOTE, type MilestoneStatus } from './knowledge.ts';
import { caseFor, type Ctx } from './engine.ts';
import type { LinkContext } from './reply.ts';

/* ---------- loyalty ---------- */

export const LOYALTY_RULES = { pointsPerRo: 100, pointsPerTenureMonth: 10 } as const;
export const LOYALTY_TIERS = [
  { name: 'Bronze', min: 0, perks: ['Multi-point inspection with every visit'] },
  { name: 'Silver', min: 300, perks: ['Multi-point inspection with every visit', 'Priority scheduling'] },
  { name: 'Gold', min: 800, perks: ['Multi-point inspection with every visit', 'Priority scheduling', 'Loaner vehicle for major milestones'] },
  { name: 'Platinum', min: 1500, perks: ['Multi-point inspection with every visit', 'Priority scheduling', 'Loaner vehicle for major milestones', 'Dedicated service advisor'] },
] as const;

export interface Loyalty { points: number; tier: string; perks: string[]; nextTier: string | null; pointsToNext: number | null; visits: number; tenureMonths: number }

export function loyaltyFor(visits: number, tenureMonths: number): Loyalty {
  const points = visits * LOYALTY_RULES.pointsPerRo + Math.max(0, tenureMonths) * LOYALTY_RULES.pointsPerTenureMonth;
  let idx = 0;
  for (let i = 0; i < LOYALTY_TIERS.length; i++) if (points >= LOYALTY_TIERS[i].min) idx = i;
  const next = LOYALTY_TIERS[idx + 1] ?? null;
  return {
    points, tier: LOYALTY_TIERS[idx].name, perks: [...LOYALTY_TIERS[idx].perks], nextTier: next?.name ?? null,
    pointsToNext: next ? next.min - points : null, visits, tenureMonths,
  };
}

/* ---------- passport ---------- */

export interface PassportMilestone {
  mileage: number; title: string; services: string[]; parts: string[]; estCost: number; criticality: string;
  status: MilestoneStatus; dueInMiles: number | null; dueBy: string; actionable: boolean;
}

export interface Passport {
  customer: { firstName: string; language: 'en' | 'es' };
  dealer: { name: string; phone: string };
  vehicle: { year: number; make: string; model: string; vin: string; odometer: number | null; odometerEstimated: boolean; deliveredAt: string; warrantyEnd: string | null };
  loyalty: Loyalty;
  roadmap: { delivery: string; milestones: PassportMilestone[]; next: PassportMilestone | null; source: 'oem' | 'generic'; note: string };
  equityPeak: { month: number; date: string; basis: string; passed: boolean };
  recalls: Array<{ campaign: string; component: string; summary: string; remedy: string; asOf: string }>;
  triage: Array<{ kind: string; urgency: string; symbol: string; system: string; message: string; at: string }>;
  maxUploadMb: { image: number; audio: number };
}

export function buildPassport(ctx: Ctx, link: LinkContext): Passport | null {
  const db = ctx.db;
  const row = get<{
    full_name: string; language: string; rooftop_name: string; rooftop_phone: string; started_at: string; last_service_at: string | null; last_service_odometer: number | null;
    vin: string; year: number; make: string; model: string; odometer: number | null; odometer_at: string | null; annual_miles: number; warranty_end_date: string | null;
  }>(db, `SELECT c.full_name, c.language, r.name AS rooftop_name, r.phone AS rooftop_phone, o.started_at, o.last_service_at, o.last_service_odometer,
      v.vin, v.year, v.make, v.model, v.odometer, v.odometer_at, v.annual_miles, v.warranty_end_date
    FROM ownerships o JOIN customers c ON c.id = o.customer_id JOIN rooftops r ON r.id = o.rooftop_id JOIN vehicles v ON v.vin = o.vin
    WHERE o.id = ? AND o.tenant_id = ?`, link.ownershipId, link.tenantId);
  if (!row) return null;
  const now = clock.now();
  const est = estimateMiles(row.odometer, row.odometer_at, row.annual_miles, now).miles;
  const rm = vehicleRoadmap({ make: row.make, model: row.model, deliveredAt: row.started_at, estimatedMiles: est,
    lastServiceOdometer: row.last_service_odometer, lastServiceAt: row.last_service_at, now });
  const toPm = (i: (typeof rm.items)[number]): PassportMilestone => ({
    mileage: i.milestone.mileage, title: i.milestone.title, services: i.milestone.requiredServices, parts: i.milestone.parts, estCost: i.milestone.estCost,
    criticality: i.milestone.criticality, status: i.status, dueInMiles: i.dueInMiles, dueBy: i.dueBy, actionable: i === rm.next,
  });
  const milestones = rm.items.map(toPm);
  const visits = Number(get<{ n: number }>(db, 'SELECT COUNT(*) AS n FROM ro_history WHERE tenant_id = ? AND ownership_id = ?', link.tenantId, link.ownershipId)?.n ?? 0);
  const tenureMonths = Math.floor(daysBetween(new Date(row.started_at), now) / 30.44);
  const triage = all<{ kind: string; urgency: string; symbol: string; system: string; customer_message: string; created_at: string }>(db,
    `SELECT t.kind, t.urgency, t.symbol, t.system, t.customer_message, t.created_at FROM triage_results t JOIN cases k ON k.id = t.case_id
     WHERE t.tenant_id = ? AND k.ownership_id = ? ORDER BY t.created_at DESC LIMIT 5`, link.tenantId, link.ownershipId)
    .map((t) => ({ kind: t.kind, urgency: t.urgency, symbol: t.symbol, system: t.system, message: t.customer_message, at: t.created_at }));
  return {
    customer: { firstName: row.full_name.split(' ')[0] || 'there', language: row.language === 'es' ? 'es' : 'en' },
    dealer: { name: row.rooftop_name, phone: row.rooftop_phone },
    vehicle: { year: row.year, make: row.make, model: row.model, vin: row.vin, odometer: est ?? row.odometer, odometerEstimated: est != null,
      deliveredAt: row.started_at.slice(0, 10), warrantyEnd: row.warranty_end_date ? row.warranty_end_date.slice(0, 10) : null },
    loyalty: loyaltyFor(visits, tenureMonths),
    roadmap: { delivery: row.started_at.slice(0, 10), milestones, next: milestones.find((m) => m.actionable) ?? null, source: rm.source, note: SCHEDULE_SOURCE_NOTE },
    equityPeak: equityPeak(row.started_at, row.annual_miles, row.warranty_end_date, now),
    recalls: ctx.recall.openFindings(link.tenantId, row.vin).map((r) => ({ campaign: r.campaign, component: r.component, summary: r.summary, remedy: r.remedy, asOf: r.as_of })),
    triage,
    maxUploadMb: { image: Math.round(ctx.cfg.limits.imageBytes / 1048576), audio: Math.round(ctx.cfg.limits.audioBytes / 1048576) },
  };
}

/**
 * The only facts the garage chat may use. Numbers are pre-formatted the way an answer would quote them
 * ("30,000", "$410") so checkDraft can match every number in the model's answer.
 */
export function passportFacts(p: Passport): Record<string, unknown> {
  return {
    vehicle: `${p.vehicle.year} ${p.vehicle.make} ${p.vehicle.model}`,
    estimatedOdometer: p.vehicle.odometer != null ? fmtMiles(p.vehicle.odometer) : 'unknown',
    dealer: p.dealer.name,
    warrantyEnd: p.vehicle.warrantyEnd ?? 'unknown',
    scheduleNote: p.roadmap.note,
    milestones: p.roadmap.milestones.map((m) => ({
      title: m.title, mileage: fmtMiles(m.mileage), status: m.status, services: m.services, parts: m.parts, estimatedCost: `$${m.estCost}`,
      dueIn: m.dueInMiles == null ? 'unknown' : m.dueInMiles >= 0 ? `${fmtMiles(m.dueInMiles)} miles` : `${fmtMiles(-m.dueInMiles)} miles ago`, dueBy: m.dueBy,
    })),
    openRecalls: p.recalls.map((r) => ({ campaign: r.campaign, component: r.component, summary: r.summary, remedy: r.remedy })),
    loyalty: { tier: p.loyalty.tier, points: String(p.loyalty.points), perks: p.loyalty.perks, nextTier: p.loyalty.nextTier, pointsToNext: p.loyalty.pointsToNext == null ? null : String(p.loyalty.pointsToNext) },
  };
}

/** Deterministic answer used when the model is off, fails validation or its answer fails guardrails. */
export function fallbackAnswer(p: Passport): string {
  const es = p.customer.language === 'es';
  const n = p.roadmap.next;
  if (!n) return es ? `Un asesor de ${p.dealer.name} le respondera pronto.` : `A ${p.dealer.name} advisor will follow up with your question shortly.`;
  return es
    ? `Su proximo servicio es ${n.title}: ${n.services.join(', ')} (est. $${n.estCost}). Un asesor de ${p.dealer.name} puede responder mas preguntas.`
    : `Your next service is the ${n.title}: ${n.services.join(', ')} (est. $${n.estCost}). A ${p.dealer.name} advisor can answer anything else.`;
}

/** "Book" from the roadmap: opens a callback case for the advisor (no calendar integration in the prototype). */
export function requestBooking(ctx: Ctx, link: LinkContext, milestoneMileage: number | null): { caseId: string; title: string | null } {
  const p = buildPassport(ctx, link);
  const m = p?.roadmap.milestones.find((x) => x.mileage === milestoneMileage) ?? p?.roadmap.next ?? null;
  return tx(ctx.db, () => {
    const caseId = caseFor(ctx, link.tenantId, link.rooftopId, link.ownershipId, link.customerId, 'callback', 'P2',
      m ? `Garage booking request: ${m.title}` : 'Garage booking request',
      m ? `Customer tapped Book for ${m.title} (${m.services.join(', ')}; est. $${m.estCost}). Call to schedule.` : 'Customer tapped Book. Call to schedule.');
    run(ctx.db, `UPDATE ownerships SET unanswered_count = 0, updated_at = ? WHERE id = ?`, clock.iso(), link.ownershipId);
    audit(ctx.db, link.tenantId, 'customer:garage', 'garage.book', caseId, { milestone: m?.mileage ?? null });
    return { caseId, title: m?.title ?? null };
  });
}
